class AppStore extends ChangeNotifier {
  SharedPreferences? prefs;
  final Set<String> completed = {};
  final Set<String> downloadedPacks = {};
  bool dark = false;
  bool english = false;
  bool notificationsEnabled = true;
  bool showHints = true;
  String cadChoice = 'Fusion 360';
  String languageChoice = 'C++';
  int xp = 0;
  Future<void> load() async {
    prefs = await SharedPreferences.getInstance();
    completed.addAll(prefs?.getStringList('completed') ?? []);
    downloadedPacks.addAll(prefs?.getStringList('downloadedPacks') ?? []);
    dark = prefs?.getBool('dark') ?? false;
    english = prefs?.getBool('english') ?? false;
    notificationsEnabled = prefs?.getBool('notificationsEnabled') ?? true;
    showHints = prefs?.getBool('showHints') ?? true;
    xp = prefs?.getInt('xp') ?? 0;
    cadChoice = prefs?.getString('cadChoice') ?? 'Fusion 360';
    languageChoice = prefs?.getString('languageChoice') ?? 'C++';
  }
  Future<void> finish(Lesson l) async {
    if (completed.add(l.id)) {
      xp += l.xp;
      await prefs?.setStringList('completed', completed.toList());
      await prefs?.setInt('xp', xp);
      notifyListeners();
    }
  }
  Future<void> toggleTheme(bool v) async { dark=v; await prefs?.setBool('dark',v); notifyListeners(); }
  Future<void> toggleLanguage(bool v) async { english=v; await prefs?.setBool('english',v); notifyListeners(); }
  Future<void> setCad(String v) async { cadChoice=v; await prefs?.setString('cadChoice',v); notifyListeners(); }
  Future<void> setLanguageChoice(String v) async { languageChoice=v; await prefs?.setString('languageChoice',v); notifyListeners(); }
  Future<void> toggleNotifications(bool v) async { notificationsEnabled=v; await prefs?.setBool('notificationsEnabled',v); notifyListeners(); }
  Future<void> toggleHints(bool v) async { showHints=v; await prefs?.setBool('showHints',v); notifyListeners(); }
  Future<void> downloadCategory(String course, String category) async {
    final key = '$course::$category';
    final pack = lessons.where((l) => l.course == course && l.category == category).toList();
    if (pack.isEmpty) return;
    await prefs?.setString('offline_pack_$key', jsonEncode(pack.map((l) => l.toJson()).toList()));
    downloadedPacks.add(key);
    await prefs?.setStringList('downloadedPacks', downloadedPacks.toList());
    notifyListeners();
  }
  Future<void> downloadCourse(String course) async {
    final categories = lessons.where((l) => l.course == course).map((l) => l.category).toSet();
    for (final category in categories) { await downloadCategory(course, category); }
  }
  Future<void> downloadEverything() async {
    final ids = lessons.map((l) => l.course).toSet();
    for (final id in ids) { await downloadCourse(id); }
  }
  bool isPackDownloaded(String course, String category) => downloadedPacks.contains('$course::$category');
  int get offlineStorageBytes => downloadedPacks.fold<int>(0, (sum, key) => sum + (((prefs?.getString('offline_pack_$key') == null) ? 0 : utf8.encode(prefs!.getString('offline_pack_$key')!).length)));
  Future<void> clearOfflinePacks() async {
    for (final key in downloadedPacks) { await prefs?.remove('offline_pack_$key'); }
    downloadedPacks.clear();
    await prefs?.setStringList('downloadedPacks', []);
    notifyListeners();
  }
  Future<void> resetProgress() async {
    completed.clear(); xp = 0;
    await prefs?.setStringList('completed', []);
    await prefs?.setInt('xp', 0);
    notifyListeners();
  }
  int get level => 1 + (xp ~/ 100);
  int get xpInLevel => xp % 100;
  double get overall => lessons.isEmpty ? 0 : completed.length / lessons.length;
  bool isUnlocked(String course) {
    if (course == 'mechanics_diag') return lessons.where((l)=>l.course=='mechanics').every((l)=>completed.contains(l.id));
    if (course == 'electromech') {
      final mechanicsDone = lessons.where((l)=>l.course=='mechanics').every((l)=>completed.contains(l.id));
      final electronicsDone = lessons.where((l)=>l.course=='electronics').every((l)=>completed.contains(l.id));
      return mechanicsDone && electronicsDone;
    }
    if (course == 'arduino') return lessons.where((l)=>l.course=='electronics').every((l)=>completed.contains(l.id));
    return true;
  }
  double progress(String course) {
    final ls = lessons.where((l)=>l.course==course).toList();
    if (ls.isEmpty) return 0;
    return ls.where((l)=>completed.contains(l.id)).length / ls.length;
  }
}

class TechnikAI extends StatelessWidget {
  final AppStore store;
  const TechnikAI({super.key, required this.store});
  @override
  Widget build(BuildContext context) => AnimatedBuilder(
    animation: store,
    builder: (_,__) => MaterialApp(
      debugShowCheckedModeBanner:false,
      title:'TECHNIK AI',
      themeMode: store.dark ? ThemeMode.dark : ThemeMode.light,
      theme: ThemeData(colorSchemeSeed: const Color(0xFF286F9C), useMaterial3:true, brightness:Brightness.light),
      darkTheme: ThemeData(colorSchemeSeed: const Color(0xFF63B6D8), useMaterial3:true, brightness:Brightness.dark),
      home: MainShell(store:store),
    ),
  );
}

class MainShell extends StatefulWidget {
  final AppStore store;
  const MainShell({super.key,required this.store});
  @override State<MainShell> createState()=>_MainShellState();
}
class _MainShellState extends State<MainShell> {
  int index=0;
  @override Widget build(BuildContext context) {
    final store=widget.store;
    final pages=[
      LearnPage(store:store),
      ProgressPage(store:store),
      WorkshopPage(store:store),
      ProfilePage(store:store),
    ];
    return Scaffold(
      body:SafeArea(child:pages[index]),
      bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(v)=>setState(()=>index=v),destinations:const[
        NavigationDestination(icon:Icon(Icons.menu_book_outlined),selectedIcon:Icon(Icons.menu_book),label:'Nauka'),
        NavigationDestination(icon:Icon(Icons.insights_outlined),selectedIcon:Icon(Icons.insights),label:'Postępy'),
