class CoursePage extends StatelessWidget {
  final AppStore store;
  final Course course;
  const CoursePage({super.key, required this.store, required this.course});

  @override
  Widget build(BuildContext context) => AnimatedBuilder(
    animation: store,
    builder: (context, _) {
      final grouped = <String, List<Lesson>>{};
      for (final lesson in lessons.where((l) => l.course == course.id)) {
        grouped.putIfAbsent(lesson.category, () => []).add(lesson);
      }
      final all = lessons.where((l) => l.course == course.id).toList();
      final done = all.where((l) => store.completed.contains(l.id)).length;
      return Scaffold(
        appBar: AppBar(title: Text(course.title)),
        body: ListView(
          padding: const EdgeInsets.all(16),
          children: [
            Card(
              color: course.color.withOpacity(.12),
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(course.subtitle, style: Theme.of(context).textTheme.titleMedium),
                    const SizedBox(height: 8),
                    Text('$done z ${all.length} lekcji ukończonych'),
                    const SizedBox(height: 8),
                    LinearProgressIndicator(value: all.isEmpty ? 0 : done / all.length),
                    const SizedBox(height: 12),
                    SizedBox(
                      width: double.infinity,
                      child: FilledButton.icon(
                        onPressed: () => store.downloadCourse(course.id),
                        icon: const Icon(Icons.download_for_offline),
                        label: const Text('Zapisz cały kurs offline'),
                      ),
                    ),
                    if (course.id.startsWith('cad_')) ...[
                      const SizedBox(height: 8),
                      Text('Program: ${course.title.replaceFirst('CAD: ', '')}'),
                    ],
                  ],
                ),
              ),
            ),
            const SizedBox(height: 8),
            Text('Kategorie i tematy', style: Theme.of(context).textTheme.titleLarge),
            const SizedBox(height: 8),
            ...grouped.entries.map((entry) {
              final categoryLessons = entry.value;
              final categoryDone = categoryLessons.where((l) => store.completed.contains(l.id)).length;
              final downloaded = store.isPackDownloaded(course.id, entry.key);
              return Card(
                clipBehavior: Clip.antiAlias,
                child: ExpansionTile(
                  initiallyExpanded: entry.key == grouped.keys.first,
                  leading: CircleAvatar(child: Text('${categoryLessons.length}')),
                  title: Text(entry.key, style: const TextStyle(fontWeight: FontWeight.w700)),
                  subtitle: Text('$categoryDone/${categoryLessons.length} ukończonych • ${downloaded ? "zapisano offline" : "niezapisano offline"}'),
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(12, 0, 12, 8),
                      child: SizedBox(
                        width: double.infinity,
                        child: OutlinedButton.icon(
                          onPressed: () => store.downloadCategory(course.id, entry.key),
                          icon: Icon(downloaded ? Icons.download_done : Icons.download),
                          label: Text(downloaded ? 'Zapisano ponownie' : 'Zapisz kategorię offline'),
                        ),
                      ),
                    ),
                    ...List.generate(categoryLessons.length, (i) {
                      final lesson = categoryLessons[i];
                      final isDone = store.completed.contains(lesson.id);
                      return ListTile(
                        leading: CircleAvatar(
                          radius: 17,
                          child: isDone ? const Icon(Icons.check, size: 18) : Text('${i + 1}'),
                        ),
                        title: Text(lesson.title),
                        subtitle: Text('${lesson.xp} XP • teoria + przykład + zadanie'),
                        trailing: const Icon(Icons.chevron_right),
                        onTap: () => Navigator.push(
                          context,
                          MaterialPageRoute(builder: (_) => LessonPage(store: store, lesson: lesson)),
                        ),
                      );
                    }),
                  ],
                ),
              );
            }),
          ],
        ),
      );
    },
  );
}

