class TransistorSimulationPage extends StatefulWidget {
  const TransistorSimulationPage({super.key});
  @override State<TransistorSimulationPage> createState() => _TransistorSimulationPageState();
}

class _TransistorSimulationPageState extends State<TransistorSimulationPage> {
  double baseVoltage = 0;
  double baseResistance = 10000;
  double collectorResistance = 1000;
  double supplyVoltage = 9;

  @override
  Widget build(BuildContext context) {
    const beta = 100.0;
    const baseDrop = 0.7;
    const saturationDrop = 0.2;
    final baseCurrent = baseVoltage <= baseDrop ? 0.0 : (baseVoltage - baseDrop) / baseResistance;
    final activeCollectorCurrent = beta * baseCurrent;
    final maximumCollectorCurrent = (supplyVoltage - saturationDrop) / collectorResistance;
    final saturated = activeCollectorCurrent >= maximumCollectorCurrent && baseCurrent > 0;
    final collectorCurrent = baseCurrent == 0 ? 0.0 : (saturated ? maximumCollectorCurrent : activeCollectorCurrent);
    final collectorVoltage = supplyVoltage - collectorCurrent * collectorResistance;
    final state = baseCurrent == 0 ? 'ODCIĘCIE' : (saturated ? 'NASYCENIE' : 'ZAKRES AKTYWNY');

    return Scaffold(
      appBar: AppBar(title: const Text('Tranzystor NPN – układ WE')),
      body: ListView(
        padding: const EdgeInsets.all(18),
        children: [
          const Text('Model edukacyjny niskonapięciowego układu wspólnego emitera (WE). Tranzystor NPN steruje prądem kolektora za pomocą prądu bazy. To uproszczony model, a nie dokładny symulator SPICE.'),
          const SizedBox(height: 14),
          Card(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('Stan tranzystora: $state', style: Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight: FontWeight.bold)),
                  const SizedBox(height: 12),
                  Text('Prąd bazy: ${(baseCurrent * 1000).toStringAsFixed(2)} mA'),
                  Text('Prąd kolektora: ${(collectorCurrent * 1000).toStringAsFixed(2)} mA'),
                  Text('Napięcie kolektor–emiter: ${collectorVoltage.toStringAsFixed(2)} V'),
                  const SizedBox(height: 10),
                  LinearProgressIndicator(value: (collectorCurrent / (maximumCollectorCurrent <= 0 ? 1 : maximumCollectorCurrent)).clamp(0.0, 1.0).toDouble()),
                  const SizedBox(height: 8),
                  Text(saturated
                    ? 'Tranzystor jest w nasyceniu: prąd ogranicza głównie obwód kolektora i rezystor RC.'
                    : (baseCurrent == 0
                      ? 'Tranzystor jest zatkany: baza nie otrzymuje wystarczającego napięcia.'
                      : 'Tranzystor pracuje w przybliżonym zakresie aktywnym; zmiana prądu bazy wpływa na prąd kolektora.')),
                ],
              ),
            ),
          ),
          const SizedBox(height: 12),
          _slider('Napięcie sterujące bazy', baseVoltage, 0, 5, (v) => setState(() => baseVoltage = v), '${baseVoltage.toStringAsFixed(1)} V'),
          _slider('Rezystor bazy RB', baseResistance, 1000, 100000, (v) => setState(() => baseResistance = v), '${baseResistance.round()} Ω'),
          _slider('Rezystor kolektora RC', collectorResistance, 100, 10000, (v) => setState(() => collectorResistance = v), '${collectorResistance.round()} Ω'),
          _slider('Zasilanie kolektora', supplyVoltage, 5, 12, (v) => setState(() => supplyVoltage = v), '${supplyVoltage.toStringAsFixed(1)} V'),
          const Card(
            child: Padding(
              padding: EdgeInsets.all(14),
              child: Text('Założenia modelu: UBE ≈ 0,7 V, UCE(sat) ≈ 0,2 V i wzmocnienie β = 100. Rzeczywiste parametry zależą od konkretnego tranzystora, temperatury i prądu. Zaczynaj od niskiego napięcia i ograniczenia prądu.'),
            ),
          ),
          OutlinedButton(
            onPressed: () => setState(() { baseVoltage = 0; baseResistance = 10000; collectorResistance = 1000; supplyVoltage = 9; }),
            child: const Text('Przywróć ustawienia początkowe'),
          ),
        ],
      ),
    );
  }

  Widget _slider(String label, double value, double min, double max, ValueChanged<double> onChanged, String readout) => Column(
    crossAxisAlignment: CrossAxisAlignment.start,
    children: [
      Row(children: [Expanded(child: Text(label)), Text(readout, style: const TextStyle(fontWeight: FontWeight.bold))]),
      Slider(value: value, min: min, max: max, onChanged: onChanged),
    ],
  );
}

